"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4650],{84650:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-sentyabr-2026-toplivo","locale":"ru","title":"Дорогое топливо разогнало инфляцию в США до 3,7% и тянет за собой другие цены","description":"В сентябре 2026 года инфляция в США выросла до 3,7%, базовая до 2,6%. Как дорогое топливо переходит в другие цены и что показывают данные по России.","blocks":[{"id":"b001","kind":"paragraph","text":"В сентябре 2026 года потребительские цены в США выросли на 3,7% за год, в августе было 3,4%, аналитики ждали 3,6%. За месяц цены прибавили 0,6%, и больше половины этого роста дал бензин: +9,1% за сентябрь, +34,2% за год. Вся энергия подорожала на 20,4% за год. Но ускорилась и базовая инфляция, без еды и энергии: 2,6% против 2,4% в августе и 2,5% в прогнозах."},{"id":"b002","kind":"paragraph","text":"Так топливо расходится по ценам. Пекарня возит хлеб в магазины на своём фургоне. Дизель подорожал, и сначала пекарня добавляет к счёту доплату за доставку. Магазин через пару месяцев переносит её в цену батона. Дальше дорожают кафе, которое покупает этот хлеб, и такси, на котором ездит повар. Это называют вторичными эффектами: шок в одной цене расползается на те, что с ним напрямую не связаны. В региональном обзоре ФРС \xabБежевая книга\xbb дорогая нефть упоминается в отчётах всех 12 округов, а компании жалуются на дизель и доплаты за топливо по всей цепочке поставок."},{"id":"b003","kind":"paragraph","text":"Для Федеральной резервной системы США это плохой знак. Ставка сейчас 3,75–4%, в сентябре её повысили на четверть пункта. Президент ФРБ Чикаго Остин Гулсби назвал отчёт обескураживающим: инфляция в услугах выше 5% и почти не снижается. Шанс повышения ставки 27–28 октября после отчёта вырос с 21,6% до 32,7%. Доллар после отчёта подорожал к другим валютам, американские акции упали, S&P 500 на 1,11%."},{"id":"b004","kind":"paragraph","text":"В России топливо тоже дорожает быстрее остальных цен, хотя причины свои, перебои и ремонты на НПЗ. Если оно так же уйдёт в доставку, вслед подорожают и другие товары. С начала года по 12 октября бензин подорожал на 21,4%, дизель на 13,5%, а все цены на 6,1%. За неделю с 6 по 12 октября инфляция замедлилась до 0,11% после скачка на 0,96% из-за тарифов ЖКХ, но продукты подорожали на 0,21%, яйца на 2,4%."},{"id":"b005","kind":"paragraph","text":"Банк России ждёт по итогам 2026 года 6–7%. Чтобы не выйти за 7%, цены до конца года должны вырасти не больше чем на 0,85% (1,07 / 1,061). Это около 0,07% в неделю, а последняя неделя дала 0,11%. Аналитики в опросе Банка России ждут 7,1%. Новый прогноз и решение по ставке регулятор объявит 23 октября."},{"id":"b006","kind":"paragraph","text":"Если вторичные эффекты от топлива окажутся слабыми, недельная инфляция вернётся к 0,07% и ниже, и у Банка России появится повод думать о снижении ставки. Если доставка, услуги и продукты продолжат дорожать вслед за бензином, ставка 14% продержится дольше: кредиты останутся дорогими, а вклады доходными."},{"id":"b007","kind":"heading","text":"Почему инфляция в США выросла в сентябре 2026 года?"},{"id":"b008","kind":"paragraph","text":"Главная причина в бензине, он подорожал на 9,1% за месяц и на 34,2% за год и дал больше половины месячного роста цен. Но базовая инфляция без еды и энергии тоже ускорилась, с 2,4% до 2,6%. Компании в обзоре ФРС жалуются на доплаты за топливо по всей цепочке поставок, а часть из них ещё и на пошлины на импорт."},{"id":"b009","kind":"heading","text":"Повысит ли ФРС ставку из-за инфляции?"},{"id":"b010","kind":"paragraph","text":"Это не решено. После отчёта рынок оценивал шанс повышения на заседании 27–28 октября в 32,7% против 21,6% накануне. Сейчас ставка ФРС 3,75–4%."},{"id":"b011","kind":"heading","text":"Уложится ли инфляция в России в прогноз Банка России в 2026 году?"},{"id":"b012","kind":"paragraph","text":"С начала года по 12 октября цены выросли на 6,1%. Чтобы годовая инфляция не превысила 7%, верхнюю границу прогноза Банка России, до конца года цены должны вырасти не больше чем на 0,85%. Аналитики в опросе Банка России ждут 7,1%, новый прогноз регулятор даст 23 октября."}],"sources":[{"label":"Inflation surged in September as U.S. energy costs jumped","url":"https://finance.yahoo.com/economy/articles/inflation-surged-september-u-energy-125137111.html"},{"label":"Higher fuel costs lead to price increases, businesses warn the Fed","url":"https://finance.yahoo.com/economy/policy/articles/higher-fuel-costs-lead-price-192929072.html"},{"label":"Fed\'s Goolsbee says September CPI \'discouraging\'","url":"https://finance.yahoo.com/economy/policy/articles/feds-goolsbee-says-september-cpi-193440276.html"},{"label":"Dollar ticks up, gold slides on US inflation news","url":"https://finance.yahoo.com/markets/currencies/articles/dollar-ticks-gold-slides-on-us-inflation-news-193351444.html"},{"label":"Уолл-стрит в среду снизилась из-за ускорения инфляции в США","url":"https://www.interfax.ru/business/1122532"},{"label":"Инфляция в России с 6 по 12 октября составила 0,11%, годовая ускорилась до 7,22%","url":"https://www.interfax.ru/business/1122459"},{"label":"Инфляция за период с 6 по 12 октября составила 0,11%","url":"https://www.vedomosti.ru/economics/news/2026/10/14/1237099-inflyatsiya-sostavila"}],"sourceBodySha256":"28f2c644ef71d7bb0798565c5d39754497c35d4acc2f2fb91243b4680ba43a81"}')}}]);